const mongoose = require('mongoose');

const transactionSchema = new mongoose.Schema(
  {

    //foreign key reference to freelancer
    freelancerId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'A transaction must belong to a freelancer']
    },

    //foreign key reference to booking
    bookingId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Booking',
      required: [true, 'A transaction must belong to a booking']
    },

    // *****autogenerated*****
    //transaction ID
    // transactionId: {
    //   type: mongoose.Schema.Types.ObjectId,
    //   ref: 'Transaction',
    //   required: [true, 'A transaction must have an ID'],
    // },
    

    //date transaction took place
    // createdAt: {
    //   type: date,
    //   default: date.now
    // },

    //no way to automatically pull the price/amount from the booking - have to do this in controller
   amount: {
      type: Number,
      required: [true, 'Transaction amount is required'],
      min: [0, 'Transaction amount cannot be negative']
    },

    //transaction status - defaults to compeleted in order to simulate successful booking
    status: {
      type: String,
      enum: ['pending', 'completed', 'refunded'],
      default: 'completed'
    }
  },
  { timestamps: true }
);

module.exports = mongoose.model('Transaction', transactionSchema);